style.css:
@-moz-document domain("roblox.com"), domain("www.roblox.com") {
body {
        background: url("https://i.imgur.com/MdyD5On.jpeg") no-repeat center center fixed !important;
        background-size: cover !important;
    }

    /* Optional: Make page content semi-transparent */
    .container-main, .content, .game-home-page, .games-page, .profile-container, .navbar {
        background-color: rgba(255, 255, 255, 0.8) !important;
    }

    /* Optional: Hide Roblox's default background elements */
    .rbx-body, .main-content, #navigation {
        background: transparent !important;
    }
}
